;-- -. . -..- - / . -. - .-. -.--
SELECT * FROM SIM_CARGA_RESERVAS WHERE SECUENCIA_CAR_EXPE IN (1785823);
;-- -. . -..- - / . -. - .-. -.--
SELECT * FROM SIM_CARGA_RESERVAS;
;-- -. . -..- - / . -. - .-. -.--
SELECT
    SECUENCIA_CAR_EXPE,
    TIPO_EXPED,
    COUNT(*) AS CANTIDAD_REGISTROS,
    LISTAGG(COD_COB, ', ') WITHIN GROUP (ORDER BY COD_COB) AS COBERTURAS,
    LISTAGG(CONSECUTIVO, ', ') WITHIN GROUP (ORDER BY CONSECUTIVO) AS CONSECUTIVOS,
    MIN(FECHA_CREACION) AS PRIMERA_CREACION,
    MAX(FECHA_MODIFICACION) AS ULTIMA_MODIFICACION
FROM
    SIM_CARGA_RESERVAS
WHERE
    COD_CIA = 3
  AND COD_SECC = 37
  AND COD_RAMO = 486
  AND PROCESO = 70
GROUP BY
    SECUENCIA_CAR_EXPE,
    TIPO_EXPED
HAVING
    COUNT(*) > 1
ORDER BY
    SECUENCIA_CAR_EXPE,
    TIPO_EXPED;
;-- -. . -..- - / . -. - .-. -.--
select * from OPS$PUMA.SIM_CARGA_EXPEDIENTES where SECUENCIA = '1831141';
