from SIM_CARGA_RESERVAS
WHERE SECUENCIA_CAR_EXPE IN (1831141);
;-- -. . -..- - / . -. - .-. -.--
select *
from SIM_CARGA_RESERVAS
where PROCESO = 70
  and COD_SECC = 37
  and cod_ramo = 486
  and TIPO_EXPED = 'ARR'
  AND COD_COB IN (716, 717);
;-- -. . -..- - / . -. - .-. -.--
select *
from SIM_CARGA_RESERVAS_HI
where PROCESO = 70
  and COD_SECC = 37
  and cod_ramo = 486
  and TIPO_EXPED = 'ARR'
  AND COD_COB IN (716, 717);
