                z.mca_val_sini,
                z.suma_aseg,
                z.val_asegurable,
                NULL,
                z.porc_ppago,
                21420000,
                0,
                21420000 - 0,
                NULL,
                z.nomina,
                27302286240,
                x.cod_agravante,
                x.cod_rebaja,
                NULL,
                z.tipo_franq,
                z.fec_vig_franq
