WHERE x.cod_cia = 3
  AND x.cod_secc = '999'
  AND x.tipo_exped = 'ARR'
  AND x.cod_causa IN (993, '98')
  AND y.cod_cia = 3
  AND y.cod_secc = 37
  AND y.tipo_exped IS NULL
  AND y.cod_causa IN (993, '98')
